import{_ as r,C as t,o as i,c as s,E as a,a2 as d}from"./chunks/framework.BOeh4kYD.js";const l="/joinwell52/assets/execution-facts-20260915/approval-setting.figure.en.svg",w=JSON.parse('{"title":"Why did the tool run when the setting said “always”?","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"Why did the tool run when the setting said “always”?","date":"2026-09-15","published_date":"2026-09-15","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"Why did the tool run when the setting said “always”?","summary":"An approval setting meant to make an AI ask first instead let its tool run. Testing the fix exposed a second question: what if the approval check gives no answer?","cover":"/assets/execution-facts-20260915/approval-setting.cover-v1.png","language":"en","lifecycle":"Published","publication_authorized":true,"evidence_status":"Bounded pinned-source experiments; scope in article","pageClass":"execution-facts-article"},"headers":[],"relativePath":"en/engineering/2026-09-15-approval-setting.md","filePath":"en/engineering/2026-09-15-approval-setting.md","lastUpdated":1789442662000}'),p={name:"en/engineering/2026-09-15-approval-setting.md"};function c(h,e,u,g,m,v){const n=t("ArticleCover"),o=t("ArticleTableScroll");return i(),s("div",null,[a(n,{image:"/assets/execution-facts-20260915/approval-setting.cover-v1.png",kicker:"Open-source engineering · Experiments",title:"Why did the tool run when the setting said “always”?",summary:"An approval setting meant to make an AI ask first instead let its tool run. Testing the fix exposed a second question: what if the approval check gives no answer?",version:"2026-09-15",languageHref:"/zh/engineering/2026-09-15-approval-setting",languageLabel:"中文"}),a(o,{language:"en"}),e[0]||(e[0]=d('<h1 id="why-did-the-tool-run-when-the-setting-said-always" tabindex="-1">Why did the tool run when the setting said “always”? <a class="header-anchor" href="#why-did-the-tool-run-when-the-setting-said-always" aria-label="Permalink to &quot;Why did the tool run when the setting said “always”?&quot;">​</a></h1><p>Adding “ask me before acting” is supposed to give us another chance to check an AI&#39;s work. What should happen if that approval setting is broken?</p><p>A reasonable expectation is that the program stops and tells us what needs fixing.</p><p>Our experiment produced the opposite result. We put the text “always” into an approval setting, and the tool ran once. With the proposed fix, the same input raised an error and the tool did not run.</p><p><strong>How could a mistake in a setting intended to require approval turn into permission to act?</strong></p><h2 id="clear-meaning-invalid-setting" tabindex="-1">Clear meaning, invalid setting <a class="header-anchor" href="#clear-meaning-invalid-setting" aria-label="Permalink to &quot;Clear meaning, invalid setting&quot;">​</a></h2><p>The counterexample comes from <a href="https://github.com/openai/openai-agents-python/pull/5029" target="_blank" rel="noreferrer">a proposed OpenAI Agents Python fix</a> by DeepanshuPal. This library helps developers connect AI agents to tools.</p><p>We build a multi-agent collaboration system, so the boundary before an action matters to us. This source made that boundary testable: when an approval setting cannot be understood, does the program stop or continue?</p><p>The word “always” here is a value in program configuration, not an instruction typed into an AI chat. The problem is in the code deciding whether a tool may run, rather than a model choosing to ignore someone.</p><p>The setting accepts explicit yes/no values or a small function that decides whether approval is needed for the current action. The text “always” is not an accepted value. The old check did not report that mistake; it treated the setting as requiring no approval.</p><p>A person understands the word. That does not make it valid configuration—and invalid configuration should not silently acquire a meaning its author did not intend.</p><h2 id="leave-a-record-whenever-the-tool-runs" tabindex="-1">Leave a record whenever the tool runs <a class="header-anchor" href="#leave-a-record-whenever-the-tool-runs" aria-label="Permalink to &quot;Leave a record whenever the tool runs&quot;">​</a></h2><p>We used a local tool that adds a record to an in-memory list each time it runs. A test program stood in for the AI service; the approval check and tool-call entry point used the project&#39;s actual code.</p><p>For the comparison, we changed only the approval method, keeping the surrounding code the same.</p><table tabindex="0"><thead><tr><th>Input</th><th>Original method</th><th>Proposed fix</th></tr></thead><tbody><tr><td>Explicitly no approval needed</td><td>Run once</td><td>Run once</td></tr><tr><td>Explicitly approval needed</td><td>Wait without running</td><td>Wait without running</td></tr><tr><td>Unaccepted text “always”</td><td>Run once</td><td>Error; do not run</td></tr><tr><td>Number 1, empty value, empty object—tested separately</td><td>Run once for each</td><td>Error; do not run for each</td></tr><tr><td>A function answers no / yes</td><td>Run / wait</td><td>Run / wait</td></tr><tr><td>The decision function gives no answer</td><td>Run once</td><td><strong>Still run once</strong></td></tr></tbody></table><p>The fix stopped all four tested kinds of invalid setting while preserving normal run and wait behavior.</p><p>The last row, however, opened another question.</p><h2 id="does-no-answer-mean-no-approval-is-needed" tabindex="-1">Does no answer mean no approval is needed? <a class="header-anchor" href="#does-no-answer-mean-no-approval-is-needed" aria-label="Permalink to &quot;Does no answer mean no approval is needed?&quot;">​</a></h2><p>A fixed setting is not always enough. Developers can supply a function that examines an action and answers whether it needs approval.</p><p>We deliberately made that function return no answer. The tool still ran with the proposed fix.</p><p>Providing a function was an accepted configuration format. But its empty result was converted to “no approval needed.” <strong>An accepted setting does not necessarily produce a valid decision.</strong></p><p><img src="'+l+'" alt="An invalid setting and a missing decision are different cases"></p><p><em>Figure 1. Two mistakes reach different checks. Source: saved approval observations in sdk.json; the measured effect is a local tool invocation.</em></p><p>We are not presenting this as a confirmed new vulnerability. The function was expected to return a Boolean, and we deliberately violated that contract. The observation makes a useful follow-up question more precise:</p><p><strong>If the approval function fails or forgets to answer, should execution validate its result instead of interpreting an empty answer as permission?</strong></p><p>We tested the missing answer. Exceptions and other failure cases still need separate experiments.</p><h2 id="something-practical-to-check" tabindex="-1">Something practical to check <a class="header-anchor" href="#something-practical-to-check" aria-label="Permalink to &quot;Something practical to check&quot;">​</a></h2><p>When testing an approval feature, add “the setting itself is broken” alongside “run” and “wait.” Inspect the tool&#39;s records as well as the error message to establish whether it actually stopped.</p><p>For developers: which component checks the decision function&#39;s answer, and which invalid results must be rejected? For users: would “This setting is invalid; the action was not performed,” together with an action record, make the situation clearer?</p><p>An approval mechanism needs a defined response when it cannot produce a valid answer, as well as a normal yes/no path.</p><details><summary>Experiment details and reproduction</summary><p>The candidate was b6c2cef, exercised through RealtimeSession._handle_tool_call. The comparison substituted only _function_needs_approval from fbf59a4: a single-method ablation, not two complete releases. The tool appended to a Python list; no live service request occurred.</p><p>Ten inputs ran in each of two modes. Invalid top-level needs_approval values were the string &quot;always&quot;, integer 1, None, and an empty object. A callback returning None was a separate, deliberately out-of-contract input. The normal async callback returning false also retained its behavior.</p><p>The candidate passed the original 31 approval tests. The predecessor method produced 30 passes and one invalid-setting failure. We did not run the larger Realtime suite or verify a corresponding CodeFlowMu path.</p><p><a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/manual-runs/2026-09-15-execution-facts" target="_blank" rel="noreferrer">Pinned sources, probes, results, and reproduction instructions</a>.</p></details>',31))])}const y=r(p,[["render",c]]);export{w as __pageData,y as default};
